   | { kind: "balance-floor"; subject: Address; token: Address | null; floor: string }
   | { kind: "only-to"; subject: Address; token: Address | null; allowed: Address[] }
-  | { kind: "disclosed-within"; subject: Address; token: Address | null; hours: number };
+  | { kind: "disclosed-within"; subject: Address; token: Address | null; hours: number }
+  // The token's supply does not grow during the window. The subject IS the
+  // token contract -- there is no other address this promise is about -- and
+  // `token` must repeat it, so that generic code reading `predicate.token`
+  // (RPC log filters, renderers) sees the right contract without a special
+  // case. `file()` refuses a mismatch. `token` is non-null by type: a native
+  // asset has no Transfer-from-zero event, so "no new native coins" is not
+  // decidable from logs and cannot be expressed here at all.
+  | { kind: "no-new-mint"; subject: Address; token: Address };

 export interface Commitment {
   id: string;
@@ -223,6 +243,38 @@ export function file(c: Commitment): FilingResult {
       };
     }

+    case "no-new-mint": {
+      // One promise, one contract. A filing whose `subject` names one address
+      // and whose `token` names another would render as being "about" the
+      // first while the verifier watches the second -- a quiet
+      // misrepresentation the reader cannot see. Refused, not repaired.
+      if (p.token !== p.subject) {
+        return {
+          filed: false,
+          reason:
+            `no-new-mint is a promise about one token contract, so subject and token must be the same address; ` +
+            `got subject ${p.subject} and token ${p.token}`,
+        };
+      }
+      // Always breakable: a single mint -- a Transfer from the zero address --
+      // inside the window does it. The witness puts it under `mints[token]`,
+      // the keyed store the evaluator reads, not in `transfers`.
+      return {
+        filed: true,
+        witness: {
+          at_block,
+          at_time,
+          balances: {},
+          transfers: [],
+          mints: {
+            [p.token]: [
+              { tx: "0x" + "55".repeat(32), from: ZERO_ADDRESS, to: other, token: p.token, value: "1", at_block, at_time },
+            ],
+          },
+        },
+      };
+    }
+
     case "disclosed-within": {
       if (!Number.isFinite(p.hours) || p.hours < 0) {
         return { filed: false, reason: "hours must be a non-negative number" };
